## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/ibdPreventiveCareLogic.ts`

```typescript
/**
 * IBD Preventive Care Clinical Logic Engine
 * Based on: AGA Clinical Practice Update on Preventive Care in IBD (2023, 2025 Update)
 *           ACG Guidelines on Vaccination in IBD (2022)
 *           ECCO Consensus on Preventive Medicine in IBD (2023)
 * Key decisions: Vaccination schedule, infection risk stratification,
 *                cancer prevention (CRC, cervical, skin, lymphoma),
 *                bone health, portal vein thrombosis, cardiovascular risk
 */

export type IBDType = 'crohns' | 'uc' | 'indeterminate';
export type ImmunosuppressionLevel =
  | 'none' // No immunosuppression
  | 'low' // 5-ASA, budesonide, or low-dose prednisone <10mg/day
  | 'moderate' // Thiopurines (AZA/6-MP), methotrexate, or moderate steroids
  | 'high' // Biologics (anti-TNF, vedolizumab, ustekinumab, IL-23, JAK)
  | 'combination'; // Biologic + immunomodulator (highest risk)

export interface IBDPreventiveCareInput {
  // IBD characteristics
  ibdType: IBDType;
  ibdDurationYears: number;
  ibdExtent: 'proctitis' | 'left_sided' | 'extensive' | 'pancolitis' | 'ileal' | 'ileocolonic' | 'colonic';
  currentImmunosuppression: ImmunosuppressionLevel;
  currentMedications: string[]; // e.g., ['infliximab', 'azathioprine']

  // Vaccination status
  hasHadInfluenzaThisYear: boolean;
  hasHadPneumococcalPCV15or20: boolean;
  hasHadPneumococcalPPSV23: boolean;
  hasHadHepatitisBVaccine: boolean;
  hasHadHPVVaccine: boolean;
  hasHadVaricellaVaccine: boolean;
  hasHadZosterVaccine: boolean; // Shingrix (recombinant — safe in immunosuppressed)
  hasHadMMRVaccine: boolean;
  hasHadCOVID19Vaccine: boolean;
  hasHadMeningococcalVaccine: boolean;

  // Infection risk
  hasLatentTB: boolean;
  hasHepatitisB: boolean; // surface antigen positive
  hasHepatitisBCore: boolean; // core antibody positive (reactivation risk)
  hasHepatitisCHistory: boolean;
  hasHIV: boolean;
  hasHistoplasmosisRisk: boolean; // endemic area
  hasCoccidioidomycosisRisk: boolean; // endemic area

  // Cancer prevention
  ibdCRCSurveillanceLastYear?: number; // year of last colonoscopy
  hasPSC: boolean;
  hasPriorDysplasia: boolean;
  ageYears: number;
  sex: 'male' | 'female';
  hasHadCervicalCancerScreening: boolean; // Pap + HPV
  hasSkinExamLastYear: boolean;
  isCurrentSmoker: boolean;

  // Bone health
  hasOsteoporosis: boolean;
  hasOsteopenia: boolean;
  hasDEXALastYear?: number;
  cumulativeSteroidMonths?: number; // total months on corticosteroids
  hasVitaminDDeficiency: boolean;
  isOnCalciumVitaminD: boolean;

  // Cardiovascular / thrombosis risk
  hasPortalVeinThrombosis: boolean;
  hasVTEHistory: boolean;
  isHospitalized: boolean;
  hasActiveFlare: boolean;
  hasCardiovascularDisease: boolean;
  isOnAnticoagulation: boolean;

  // Mental health
  hasAnxietyDepression: boolean;
  hasBeenScreenedForDepression: boolean;
}

export interface IBDPreventiveCareRecommendation {
  primaryRecommendation: string;
  vaccinationSchedule: string;
  infectionRiskManagement: string;
  cancerSurveillance: string;
  boneHealthPlan: string;
  thrombosisRiskManagement: string;
  mentalHealthScreening: string;
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessIBDPreventiveCare(input: IBDPreventiveCareInput): IBDPreventiveCareRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.hasPortalVeinThrombosis) {
    urgentFlags.push('PORTAL VEIN THROMBOSIS: anticoagulation required — LMWH or DOAC. IBD patients have 3x higher PVT risk. Hematology + hepatology referral.');
  }
  if (input.hasHepatitisB && (input.currentImmunosuppression === 'high' || input.currentImmunosuppression === 'combination')) {
    urgentFlags.push('HEPATITIS B + BIOLOGIC: antiviral prophylaxis (entecavir or tenofovir) REQUIRED before starting biologic therapy — risk of HBV reactivation and fulminant hepatitis');
  }
  if (input.hasHepatitisBCore && (input.currentImmunosuppression === 'high' || input.currentImmunosuppression === 'combination')) {
    urgentFlags.push('Hepatitis B core antibody positive: monitor HBV DNA every 3 months during biologic therapy — consider prophylactic antiviral');
  }
  if (input.hasLatentTB && (input.currentImmunosuppression === 'high' || input.currentImmunosuppression === 'combination')) {
    urgentFlags.push('LATENT TB + BIOLOGIC: LTBI treatment required before starting anti-TNF (INH 9 months or rifampin 4 months). Vedolizumab/ustekinumab/IL-23 have lower TB reactivation risk.');
  }
  if (input.isHospitalized && input.hasActiveFlare) {
    urgentFlags.push('Hospitalized IBD patient: DVT prophylaxis with LMWH required — IBD patients have 3x higher VTE risk during hospitalization');
  }
  if (input.hasPriorDysplasia) {
    urgentFlags.push('Prior dysplasia in IBD: annual colonoscopy with chromoendoscopy required — high CRC risk');
  }

  // ─── Vaccination Schedule ─────────────────────────────────────────────────
  const vaccinationItems: string[] = [];

  if (!input.hasHadInfluenzaThisYear) {
    vaccinationItems.push('Annual influenza vaccine (inactivated — SAFE in immunosuppressed; live intranasal NOT recommended)');
    nextSteps.push('Annual influenza vaccine (inactivated)');
  }
  if (!input.hasHadPneumococcalPCV15or20) {
    vaccinationItems.push('Pneumococcal PCV15 or PCV20 (conjugate) — recommended for all IBD patients on immunosuppression');
    nextSteps.push('Pneumococcal PCV20 (or PCV15 followed by PPSV23 8 weeks later)');
  }
  if (!input.hasHadHepatitisBVaccine) {
    vaccinationItems.push('Hepatitis B vaccine series (3-dose or 2-dose Heplisav-B) — check anti-HBs titer after series');
    nextSteps.push('Hepatitis B vaccine series');
  }
  if (!input.hasHadHPVVaccine && input.ageYears <= 45) {
    vaccinationItems.push(`HPV vaccine (Gardasil 9) — recommended through age 45 for IBD patients on immunosuppression (higher cervical cancer risk)`);
    nextSteps.push('HPV vaccine (Gardasil 9)');
  }
  if (!input.hasHadZosterVaccine && input.ageYears >= 50) {
    vaccinationItems.push('Shingrix (recombinant zoster vaccine) — SAFE in immunosuppressed; 2-dose series. Recommended age ≥50 (or younger if on high-level immunosuppression)');
    nextSteps.push('Shingrix (recombinant zoster vaccine) — 2-dose series');
  }
  if (!input.hasHadVaricellaVaccine && input.currentImmunosuppression === 'none') {
    vaccinationItems.push('Varicella vaccine — LIVE vaccine: only give BEFORE starting immunosuppression (4 weeks before biologic initiation)');
  }
  if (!input.hasHadMMRVaccine && input.currentImmunosuppression === 'none') {
    vaccinationItems.push('MMR vaccine — LIVE vaccine: only give BEFORE starting immunosuppression');
  }
  if (!input.hasHadCOVID19Vaccine) {
    vaccinationItems.push('COVID-19 vaccine + booster (mRNA preferred — safe in immunosuppressed)');
    nextSteps.push('COVID-19 vaccine + booster');
  }

  const vaccinationSchedule =
    vaccinationItems.length > 0
      ? 'VACCINES DUE (AGA 2022 IBD Vaccination Guideline):\n' +
        vaccinationItems.map((v, i) => `${i + 1}) ${v}`).join('\n') +
        '\n\nKEY RULE: Live vaccines (MMR, varicella, yellow fever, live influenza) are CONTRAINDICATED in patients on moderate-high immunosuppression. Give live vaccines ≥4 weeks before starting biologic therapy.'
      : 'Vaccination status appears up to date. Annual influenza vaccine reminder. Review at each visit.';

  // ─── Infection Risk Management ────────────────────────────────────────────
  const infectionRiskManagement =
    'INFECTION RISK STRATIFICATION (AGA 2023): ' +
    `Current immunosuppression level: ${input.currentImmunosuppression}. ` +
    (input.currentImmunosuppression === 'combination'
      ? 'HIGHEST RISK: biologic + immunomodulator combination — monitor closely for opportunistic infections. '
      : '') +
    'Screening before biologic initiation: TB (IGRA), hepatitis B (HBsAg, anti-HBc, anti-HBs), hepatitis C, HIV, varicella IgG. ' +
    'Annual TB screening during anti-TNF therapy. ' +
    (input.hasHistoplasmosisRisk
      ? 'Histoplasmosis endemic area: Histoplasma urine antigen before anti-TNF initiation. '
      : '') +
    (input.hasCoccidioidomycosisRisk
      ? 'Coccidioidomycosis endemic area: Coccidioides serology before anti-TNF initiation. '
      : '') +
    'Avoid raw/undercooked foods and unpasteurized dairy. ' +
    'Travel medicine consultation before international travel.';

  // ─── Cancer Surveillance ──────────────────────────────────────────────────
  const cancerSurveillanceItems: string[] = [];

  // CRC surveillance
  if (input.ibdDurationYears >= 8 && (input.ibdExtent === 'extensive' || input.ibdExtent === 'pancolitis' || input.ibdExtent === 'ileocolonic')) {
    const interval = input.hasPSC || input.hasPriorDysplasia ? 'annual' : 'every 1–3 years';
    cancerSurveillanceItems.push(`CRC surveillance colonoscopy ${interval} with chromoendoscopy (IBD duration ≥8 years, extensive disease)`);
    if (!input.ibdCRCSurveillanceLastYear || (new Date().getFullYear() - input.ibdCRCSurveillanceLastYear) > 1) {
      nextSteps.push(`CRC surveillance colonoscopy with chromoendoscopy (${interval})`);
    }
  }

  // Cervical cancer
  if (input.sex === 'female' && !input.hasHadCervicalCancerScreening) {
    cancerSurveillanceItems.push('Annual cervical cancer screening (Pap + HPV co-test) — women on immunosuppression have higher cervical dysplasia risk');
    nextSteps.push('Annual cervical cancer screening (Pap + HPV)');
  }

  // Skin cancer
  if (!input.hasSkinExamLastYear && (input.currentImmunosuppression === 'high' || input.currentImmunosuppression === 'combination')) {
    cancerSurveillanceItems.push('Annual dermatology skin exam — anti-TNF + thiopurine combination increases non-melanoma skin cancer risk 4x');
    nextSteps.push('Annual dermatology skin exam (melanoma + non-melanoma skin cancer surveillance)');
  }

  // Lymphoma risk
  if (input.currentMedications.some(m => ['azathioprine', '6-mp', 'mercaptopurine'].includes(m.toLowerCase()))) {
    cancerSurveillanceItems.push('Thiopurine use: hepatosplenic T-cell lymphoma risk (rare but fatal) — avoid thiopurine monotherapy in young males; prefer biologic monotherapy');
  }

  const cancerSurveillance =
    cancerSurveillanceItems.length > 0
      ? 'CANCER SURVEILLANCE NEEDED:\n' + cancerSurveillanceItems.map((c, i) => `${i + 1}) ${c}`).join('\n')
      : 'Cancer surveillance appears up to date. Continue scheduled surveillance per guidelines.';

  // ─── Bone Health ──────────────────────────────────────────────────────────
  let boneHealthPlan = '';
  const needsDEXA =
    input.cumulativeSteroidMonths !== undefined && input.cumulativeSteroidMonths >= 3 ||
    input.hasOsteoporosis ||
    input.hasOsteopenia ||
    !input.hasDEXALastYear;

  if (needsDEXA) {
    boneHealthPlan =
      'BONE HEALTH (AGA 2023): ' +
      'DEXA scan recommended (cumulative steroid use ≥3 months or risk factors). ' +
      'Calcium 1000–1200mg/day + Vitamin D 600–2000 IU/day supplementation. ' +
      'Weight-bearing exercise. ' +
      (input.hasOsteoporosis
        ? 'Osteoporosis confirmed: bisphosphonate therapy (alendronate 70mg weekly) — gastroenterology + endocrinology co-management. '
        : '') +
      'Minimize steroid use — use budesonide (low systemic absorption) when possible.';
    if (!input.isOnCalciumVitaminD) {
      nextSteps.push('Start calcium 1000mg/day + vitamin D 1000–2000 IU/day supplementation');
    }
    if (!input.hasDEXALastYear) {
      nextSteps.push('DEXA scan for bone density assessment');
    }
  } else {
    boneHealthPlan = 'Bone health monitoring up to date. Continue calcium + vitamin D supplementation. DEXA every 2 years if on chronic steroids.';
  }

  // ─── Thrombosis Risk ──────────────────────────────────────────────────────
  const thrombosisRiskManagement =
    'THROMBOSIS RISK (IBD patients have 2–3x higher VTE risk): ' +
    (input.isHospitalized
      ? 'HOSPITALIZED: LMWH thromboprophylaxis required for all hospitalized IBD patients (AGA Strong Recommendation). '
      : 'Outpatient: assess VTE risk factors (active flare, immobility, prior VTE, surgery). ') +
    (input.hasVTEHistory
      ? 'Prior VTE: anticoagulation discussion with hematology. '
      : '') +
    (input.hasPortalVeinThrombosis
      ? 'Portal vein thrombosis: anticoagulation required (LMWH or DOAC) — hepatology referral. '
      : '') +
    'Avoid immobility during flares. ' +
    'JAK inhibitors (tofacitinib, upadacitinib) have additional VTE risk — use with caution in patients with prior VTE or high CV risk.';

  // ─── Mental Health ────────────────────────────────────────────────────────
  const mentalHealthScreening =
    'MENTAL HEALTH (AGA 2023 — depression/anxiety in 25–35% of IBD patients): ' +
    (!input.hasBeenScreenedForDepression
      ? 'PHQ-9 and GAD-7 screening recommended at each visit. '
      : 'Depression/anxiety screening performed. ') +
    (input.hasAnxietyDepression
      ? 'Anxiety/depression identified: psychological support referral. CBT and IBD-specific psychotherapy have evidence for quality-of-life improvement. '
      : '') +
    'IBD nurse specialist or patient navigator improves outcomes. ' +
    'IBD support groups (CCFA/Crohn\'s & Colitis Foundation) recommended.';

  if (nextSteps.length === 0) {
    nextSteps.push(
      'Review vaccination status at each IBD visit',
      'Annual influenza vaccine',
      'Infection screening before biologic initiation (TB, HBV, HCV, HIV)',
      'CRC surveillance colonoscopy per IBD duration and extent',
      'Annual cervical cancer screening (women on immunosuppression)',
      'Annual dermatology skin exam (patients on anti-TNF + thiopurine)'
    );
  }

  const rationale =
    `IBD type: ${input.ibdType}. ` +
    `Duration: ${input.ibdDurationYears} years. ` +
    `Extent: ${input.ibdExtent.replace(/_/g, ' ')}. ` +
    `Immunosuppression: ${input.currentImmunosuppression}. ` +
    `PSC: ${input.hasPSC ? 'Yes' : 'No'}. ` +
    `Prior dysplasia: ${input.hasPriorDysplasia ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      urgentFlags.length > 0
        ? urgentFlags[0]
        : vaccinationItems.length > 0
        ? `${vaccinationItems.length} vaccination(s) due. Infection screening and cancer surveillance review recommended.`
        : 'IBD preventive care review: vaccination, infection screening, cancer surveillance, and bone health appear up to date. Annual review recommended.',
    vaccinationSchedule,
    infectionRiskManagement,
    cancerSurveillance,
    boneHealthPlan,
    thrombosisRiskManagement,
    mentalHealthScreening,
    urgentFlags,
    nextSteps,
    evidenceLevel: 'B',
    rationale,
    references: [
      {
        citation: 'Farraye FA, et al. AGA Clinical Practice Guidelines on the Management of Moderate to Severe Ulcerative Colitis. Gastroenterology. 2020;158(5):1450-1461.',
        pmid: '32068001',
        url: 'https://pubmed.ncbi.nlm.nih.gov/32068001/',
      },
      {
        citation: 'Rubin DT, et al. ACG Clinical Guideline: Ulcerative Colitis in Adults. Am J Gastroenterol. 2019;114(3):384-413.',
        pmid: '30840605',
        url: 'https://pubmed.ncbi.nlm.nih.gov/30840605/',
      },
      {
        citation: 'Lichtenstein GR, et al. ACG Clinical Guideline: Vaccination in Patients with Inflammatory Bowel Disease. Am J Gastroenterol. 2022;117(3):409-426.',
        pmid: '35167504',
        url: 'https://pubmed.ncbi.nlm.nih.gov/35167504/',
      },
      {
        citation: 'Lamb CA, et al. ECCO Consensus on Preventive Medicine in Inflammatory Bowel Disease. J Crohns Colitis. 2023;17(1):1-23.',
        pmid: '35896083',
        url: 'https://pubmed.ncbi.nlm.nih.gov/35896083/',
      },
    ],
  };
}
